/**
 * Regenerates `receipts.json` with the API's own canonicalizer and signer,
 * so the SDK tests check the SDK against the real server code, not a copy.
 * Not part of the test run. From the repo root:
 *
 *   packages/phototology-api/node_modules/.bin/tsx \
 *     packages/phototology-sdk/tests/fixtures/generate-receipts.ts
 *
 * The live key is generated fresh on each run and only its public half is
 * written out. The sandbox key is public by design.
 */
import { generateKeyPairSync, createPrivateKey, sign as nodeSign } from 'crypto';
import { writeFileSync } from 'fs';
import { join } from 'path';
import { canonicalJson } from '../../../phototology-api/src/receipts/canonical';
import { createPemSigner, createSandboxSigner, signReceipt } from '../../../phototology-api/src/receipts/signer';
import type { Receipt, ReceiptPayload } from '../../../phototology-api/src/receipts/types';
import sandboxPrivateJwk from '../../../phototology-api/src/verify/sandbox-key.jwk.json';

const LIVE_KID = 'receipt-test';

function payload(over: Partial<ReceiptPayload> & Pick<ReceiptPayload, 'id' | 'livemode' | 'keyId'>): ReceiptPayload {
  return {
    type: 'phototology.receipt',
    version: 1,
    issuer: 'https://phototology.com',
    subject: { bytesSha256: 'a'.repeat(64), pHash: 'b'.repeat(16), dHash: 'c'.repeat(16) },
    analysis: {
      requestId: 'req_fixture',
      lenses: [{ id: 'dating', version: '1.2', outputSha256: 'd'.repeat(64) }],
      provider: 'gemini',
      model: 'gemini-3.1-flash',
      modelVersion: null,
      outputSha256: 'e'.repeat(64),
      analyzedAt: '2026-10-17T00:00:00.000Z',
    },
    firstSeenAt: '2026-10-17T00:00:00.000Z',
    credentials: { status: 'unread' },
    registry: { url: 'https://api.phototology.com/v2/photos/' + 'a'.repeat(64) },
    ...over,
  };
}

/** Signs any payload with the sandbox private key under any kid, bypassing signReceipt's livemode guard. */
function forge(p: ReceiptPayload, kid: string): string {
  const b64 = (s: string | Buffer) => Buffer.from(s).toString('base64url');
  const { kty, crv, x, y, d } = sandboxPrivateJwk;
  const key = createPrivateKey({ key: { kty, crv, x, y, d }, format: 'jwk' });
  const header = b64(JSON.stringify({ alg: 'ES256', kid }));
  const input = Buffer.from(`${header}.${b64(canonicalJson(p))}`, 'ascii');
  return `${header}..${b64(nodeSign('sha256', input, { key, dsaEncoding: 'ieee-p1363' }))}`;
}

async function main(): Promise<void> {
  const sandbox = createSandboxSigner();
  const { privateKey, publicKey } = generateKeyPairSync('ec', { namedCurve: 'P-256' });
  const live = createPemSigner(privateKey.export({ format: 'pem', type: 'pkcs8' }).toString(), LIVE_KID);
  const livePublicJwk = { ...publicKey.export({ format: 'jwk' }), kid: LIVE_KID, use: 'sig', alg: 'ES256' };

  const minimal = payload({ id: 'rcpt_fixture_minimal', livemode: false, keyId: 'sandbox' });
  const full = payload({
    id: 'rcpt_fixture_full',
    livemode: false,
    keyId: 'sandbox',
    subject: {
      bytesSha256: 'f'.repeat(64),
      pixelsSha256: '0'.repeat(64),
      pHash: '8f3c2a1b4d5e6f70',
      dHash: '0123456789abcdef',
      pdq: { hash: '9'.repeat(64), quality: 87 },
      iscc: 'ISCC:KECYCMZIOY36XXGZ',
    },
    analysis: {
      requestId: 'req_fixture_full',
      lenses: [
        { id: 'dating', version: '1.2', outputSha256: '1'.repeat(64) },
        { id: 'people', version: '2.0', outputSha256: '2'.repeat(64) },
        { id: 'text-content', version: '1.0', outputSha256: '3'.repeat(64) },
      ],
      provider: 'gemini',
      model: null,
      modelVersion: '2026-09',
      outputSha256: '4'.repeat(64),
      analyzedAt: '2026-10-17T12:34:56.789Z',
    },
    firstSeenAt: '2025-01-02T03:04:05.000Z',
    credentials: {
      status: 'unread',
      note: 'Content Credentials "café" ü\nline two\t  € 𝄞',
      Zeta: 1,
      alpha: [3, 1.5, -2, 0, true, null],
      _under: { z: false, a: 1e21, m: 123456789012 },
    },
  });
  const liveP = payload({ id: 'rcpt_fixture_live', livemode: true, keyId: LIVE_KID });
  const forgedLive = payload({ id: 'rcpt_fixture_forged_live', livemode: true, keyId: 'sandbox' });
  const markerOnlyLive = payload({ id: 'rcpt_fixture_marker_only', livemode: true, keyId: 'sandbox-alt' });
  const markerOnlySandbox = payload({ id: 'rcpt_fixture_marker_only_sb', livemode: false, keyId: 'sandbox-alt' });

  const ts: Receipt['timestamp'] = { status: 'pending' };
  const entry = async (name: string, p: ReceiptPayload, signature: string | Promise<string>) => ({
    name,
    canonical: canonicalJson(p),
    receipt: { payload: p, signature: await signature, timestamp: ts },
  });

  const out = {
    _comment: 'Generated by generate-receipts.ts from the API canonicalizer and signer. Do not edit by hand.',
    livePublicJwk,
    receipts: [
      await entry('sandbox-minimal', minimal, signReceipt(minimal, sandbox)),
      await entry('sandbox-full', full, signReceipt(full, sandbox)),
      await entry('live', liveP, signReceipt(liveP, live)),
    ],
    forged: [
      await entry('live-payload-sandbox-kid', forgedLive, forge(forgedLive, 'sandbox')),
      await entry('live-payload-marker-only-kid', markerOnlyLive, forge(markerOnlyLive, 'sandbox-alt')),
      await entry('sandbox-payload-marker-only-kid', markerOnlySandbox, forge(markerOnlySandbox, 'sandbox-alt')),
    ],
  };
  writeFileSync(join(__dirname, 'receipts.json'), JSON.stringify(out, null, 2) + '\n');
}

main().catch((err) => {
  console.error(err);
  process.exit(1);
});
